components.css:
.pill {
  padding: 12px 28px;
  border: 0;
  border-radius: 999px;
  background: #4f46e5;
  color: #fff;
  font: 600 16px system-ui, sans-serif;
  cursor: pointer;
  transition: transform 0.15s, box-shadow 0.15s;
}
.pill:hover { transform: translateY(-2px); box-shadow: 0 8px 20px rgb(79 70 229 / 0.35); }

.profile { display: flex; align-items: center; gap: 12px; padding: 14px 16px; border: 1px solid #dde1e9; border-radius: 14px; font: 15px system-ui, sans-serif; color: #1c2030; }
.avatar { width: 44px; height: 44px; border-radius: 50%; display: grid; place-items: center; background: #fde68a; font-weight: 700; }
.profile strong, .profile span { display: block; }
.profile span { color: #626a7d; font-size: 13px; }
.profile button { margin-left: 12px; padding: 6px 14px; border: 1px solid #4f46e5; border-radius: 8px; background: #fff; color: #4f46e5; font: inherit; font-weight: 600; cursor: pointer; }
.profile button.following { background: #4f46e5; color: #fff; }

components.js:
const button = document.querySelector('.profile button');
button.addEventListener('click', () => {
  const following = button.classList.toggle('following');
  button.textContent = following ? 'Following' : 'Follow';
});

components.css:
.toggle { display: inline-flex; align-items: center; gap: 10px; font: 16px system-ui, sans-serif; color: #1c2030; cursor: pointer; }
.toggle input { position: absolute; opacity: 0; }
.track { width: 48px; height: 28px; border-radius: 999px; background: #c5cad6; position: relative; transition: background 0.2s; }
.track::after { content: ""; position: absolute; top: 3px; left: 3px; width: 22px; height: 22px; border-radius: 50%; background: #fff; transition: transform 0.2s; }
.toggle input:checked + .track { background: #16a34a; }
.toggle input:checked + .track::after { transform: translateX(20px); }
.toggle input:focus-visible + .track { outline: 2px solid #4f46e5; outline-offset: 2px; }

components.js:
const input = document.querySelector('.toggle input');
const state = document.querySelector('.toggle .state');
input.addEventListener('change', () => {
  state.textContent = input.checked ? 'On' : 'Off';
});
